import{_ as r,a0 as a,w as s,s as l,I as o,x as t,a1 as p,A as i,ao as m}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const k=JSON.parse('{"title":"一周 GNOME 之旅：品味它和 KDE 的是是非非（第一节 介绍） | LCTT x X-CMD","titleTemplate":false,"description":"一周 GNOME 之旅：品味它和 KDE 的是是非非（第一节 介绍） | LCTT (201508) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"一周 GNOME 之旅：品味它和 KDE 的是是非非（第一节 介绍） | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"一周 GNOME 之旅：品味它和 KDE 的是是非非（第一节 介绍） | LCTT (201508) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201508/20150716 A Week With GNOME As My Linux Desktop--What They Get Right & Wrong - Page 1 - Introduction","title":"一周 GNOME 之旅：品味它和 KDE 的是是非非（第一节 介绍）","tag":"201508","desc":""},"relativePath":"201508/20150716 A Week With GNOME As My Linux Desktop--What They Get Right & Wrong - Page 1 - Introduction.md","filePath":"[post].md"}'),d={name:"201508/20150716 A Week With GNOME As My Linux Desktop--What They Get Right & Wrong - Page 1 - Introduction.md"};function u(g,e,w,D,f,h){const n=a("Link");return s(),l("div",null,[e[19]||(e[19]=o("h1",{id:"一周-gnome-之旅-品味它和-kde-的是是非非-第一节-介绍",tabindex:"-1"},[t("一周 GNOME 之旅：品味它和 KDE 的是是非非（第一节 介绍） "),o("a",{class:"header-anchor",href:"#一周-gnome-之旅-品味它和-kde-的是是非非-第一节-介绍","aria-label":"Permalink to “一周 GNOME 之旅：品味它和 KDE 的是是非非（第一节 介绍）”"},"​")],-1)),e[20]||(e[20]=o("p",null,[o("em",null,"作者声明:　如果你是因为某种神迹而在没看标题的情况下点开了这篇文章，那么我想再重申一些东西……这是一篇评论文章，文中的观点都是我自己的，不代表 Phoronix 网站和 Michael 的观点。它们完全是我自己的想法。")],-1)),o("p",null,[e[2]||(e[2]=t("另外，没错……这可能是一篇引战的文章。我希望 KDE 和 Gnome 社团变得更好一些，因为我想发起一个讨论并反馈给他们。为此，当我想指出（我所看到的）一个瑕疵时，我会尽量地做到具体而直接。这样，相关的讨论也能做到同样的具体和直接。再次声明：本文另一可选标题为“死于成千上万的",-1)),p(n,{href:"https://wiki.ubuntu.com/One%20Hundred%20Papercuts"},{default:i(()=>[...e[0]||(e[0]=[t("纸割",-1)])]),_:1}),e[3]||(e[3]=t("”（LCTT 译注：paper cuts——纸割，被纸片割伤——指易修复但烦人的缺陷。Ubuntu 从 9.10 开始，发起了 ",-1)),p(n,{href:"https://wiki.ubuntu.com/One%20Hundred%20Papercuts"},{default:i(()=>[...e[1]||(e[1]=[t("One Hundred Papercuts",-1)])]),_:1}),e[4]||(e[4]=t(" 项目，用于修复那些小而烦人的易用性问题）。",-1))]),e[21]||(e[21]=o("p",null,"现在，重申完毕……文章开始。",-1)),e[22]||(e[22]=o("p",null,[o("img",{src:"http://www.phoronix.net/image.php?id=fedora-22-fan&image=fedora_22_good1_show&w=1920",alt:""})],-1)),o("p",null,[e[6]||(e[6]=t("当我把",-1)),p(n,{href:"http://www.phoronix.com/scan.php?page=article&item=fedora-22-kde&num=1"},{default:i(()=>[...e[5]||(e[5]=[t("《评价 Fedora 22 KDE 》",-1)])]),_:1}),e[7]||(e[7]=t("一文发给 Michael 时，感觉很不是滋味。不是因为我不喜欢 KDE，或者不待见 Fedora，远非如此。事实上，我刚开始想把我的 T450s 的系统换为 Arch Linux 时，马上又决定放弃了，因为我很享受 fedora 在很多方面所带来的便捷性。",-1))]),e[23]||(e[23]=m('<p>我感觉很不是滋味的原因是 Fedora 的开发者花费了大量的时间和精力在他们的“工作站”产品上，但是我却一点也没看到。在使用 Fedora 时，我并没用采用那些主要开发者希望用户采用的那种使用方式，因此我也就体验不到所谓的“ Fedora 体验”。它感觉就像一个人评价 Ubuntu 时用的却是 Kubuntu，评价 OS X 时用的却是 Hackintosh，或者评价 Gentoo 时用的却是 Sabayon。根据论坛里大量读者对 Michael 的说法，他们在评价各种发行版时都是使用的默认设置——我也不例外。但是我还是认为这些评价应该在“真实”配置下完成，当然我也知道在给定的情况下评论某些东西也的确是有价值的——无论是好是坏。</p><p>正是在怀着这种态度的情况下，我决定跳到 Gnome 这个水坑里来泡泡澡。</p><p>但是，我还要在此多加一个声明……我在这里所看到的 KDE 和 Gnome 都是打包在 Fedora 中的。OpenSUSE、 Kubuntu、 Arch等发行版的各个桌面可能有不同的实现方法，使得我这里所说的具体的“痛点”跟你所用的发行版有所不同。还有，虽然用了这个标题，但这篇文章将会是一篇“很 KDE”的重量级文章。之所以这样称呼，是因为我在“使用” Gnome 之后，才知道 KDE 的“纸割”到底有多么的多。</p><h3 id="登录界面" tabindex="-1">登录界面 <a class="header-anchor" href="#登录界面" aria-label="Permalink to “登录界面”">​</a></h3><p><img src="http://www.phoronix.net/image.php?id=gnome-week-editorial&amp;image=gnome_week_login1_show&amp;w=1920" alt="Gnome 登录界面"></p><p>我一般情况下都不会介意发行版带着它们自己的特别主题，因为一般情况下桌面看起来会更好看。可我今天可算是找到了一个例外。</p><p>第一印象很重要，对吧？那么，GDM（LCTT 译注： Gnome Display Manage：Gnome 显示管理器。）绝对干得漂亮。它的登录界面看起来极度简洁，每一部分都应用了一致的设计风格。使用通用图标而不是文本框为它的简洁加了分。</p><p><img src="http://www.phoronix.net/image.php?id=gnome-week-editorial&amp;image=gnome_week_login2_show&amp;w=1920" alt=" KDE 登录界面"></p><p>这并不是说 Fedora 22 KDE ——现在已经是 SDDM 而不是 KDM 了——的登录界面不好看，但是看起来绝对没有它这样和谐。</p><p>问题到底出来在哪？顶部栏。看看 Gnome 的截图——你选择一个用户，然后用一个很小的齿轮简单地选择想登入哪个会话。设计很简洁，一点都不碍事，实话讲，如果你没注意的话可能完全会看不到它。现在看看那蓝色（ LCTT 译注：blue，有忧郁之意，一语双关）的 KDE 截图，顶部栏看起来甚至不像是用同一个工具渲染出来的，它的整个位置的安排好像是某人想着：“哎哟妈呀，我们需要把这个选项扔在哪个地方……”之后决定下来的。</p><p>对于右上角的重启和关机选项也一样。为什么不单单用一个电源按钮，点击后会下拉出一个菜单，里面包括重启，关机，挂起的功能？按钮的颜色跟背景色不同肯定会让它更加突兀和显眼……但我可不觉得这样子有多好。同样，这看起来可真像“苦思”后的决定。</p><p>从实用观点来看，GDM 还要远远实用的多，再看看顶部一栏。时间被列了出来，还有一个音量控制按钮，如果你想保持周围安静，你甚至可以在登录前设置静音，还有一个可用性按钮来实现高对比度、缩放、语音转文字等功能，所有可用的功能通过简单的一个开关按钮就能得到。</p><p><img src="http://www.phoronix.net/image.php?id=gnome-week-editorial&amp;image=gnome_week_login3_show&amp;w=1920" alt=""></p><p>切换到上游（KDE 自带）的 Breeve 主题……突然间，我抱怨的大部分问题都被解决了。通用图标，所有东西都放在了屏幕中央，但不是那么重要的被放到了一边。因为屏幕顶部和底部都是同样的空白，在中间也就酝酿出了一种美好的和谐。还是有一个文本框来切换会话，但既然电源按钮被做成了通用图标，那么这点还算可以原谅。当前时间以一种漂亮的感觉呈现，旁边还有电量指示器。当然 gnome 还是有一些很好的附加物，例如音量小程序和可用性按钮，但 Breeze 总归要比 Fedora 的 KDE 主题进步。</p><p>到 Windows（Windows 8和10之前）或者 OS X 中去，你会看到类似的东西——非常简洁的，“不碍事”的锁屏与登录界面，它们都没有文本框或者其它分散视觉的小工具。这是一种有效的不分散人注意力的设计。Fedora……默认带有 Breeze 主题。VDG 在 Breeze 主题设计上干得不错。可别糟蹋了它。</p><hr>',16)),o("p",null,[e[9]||(e[9]=t("via: ",-1)),p(n,{href:"http://www.phoronix.com/scan.php?page=article&item=gnome-week-editorial&num=1"},{default:i(()=>[...e[8]||(e[8]=[t("http://www.phoronix.com/scan.php?page=article&item=gnome-week-editorial&num=1",-1)])]),_:1})]),o("p",null,[e[12]||(e[12]=t("作者：Eric Griffith 译者：",-1)),p(n,{href:"https://github.com/XLCYun"},{default:i(()=>[...e[10]||(e[10]=[t("XLCYun",-1)])]),_:1}),e[13]||(e[13]=t(" 校对：",-1)),p(n,{href:"https://github.com/wxy"},{default:i(()=>[...e[11]||(e[11]=[t("wxy",-1)])]),_:1})]),o("p",null,[e[16]||(e[16]=t("本文由 ",-1)),p(n,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...e[14]||(e[14]=[t("LCTT",-1)])]),_:1}),e[17]||(e[17]=t(" 原创翻译，",-1)),p(n,{href:"https://linux.cn/"},{default:i(()=>[...e[15]||(e[15]=[t("Linux中国",-1)])]),_:1}),e[18]||(e[18]=t(" 荣誉推出",-1))])])}const x=r(d,[["render",u]]);export{k as __pageData,x as default};
